"""Report all seeds and parent-averaged effects, without choosing a winner."""
from pathlib import Path
import sys,numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.run_stvg_joint_event_critic_v1 import read,put
from scripts.run_stvg_referdino_native_opd_hc128_v1 import D,P

def main():
 z=read(P/'RESULTS_PUBLIC.json');audit=read(P/'ROOT_INDEPENDENT_AUDIT.json');assert audit['status']=='pass';cost=read(P/'COST_BREAKDOWN.json');rows=z['rows']
 def show(x):return f"{x['mean']:+.4f} [{x['CI95'][0]:+.4f}, {x['CI95'][1]:+.4f}]"
 text=['# Fixed native ReferDINO supervision: Direct / fresh Fixed / Live, HC128','', 'Actual output-box-policy OPD with a fixed cached native teacher. No teacher refresh is required by this experiment. Candidates are sampled in native output-box logits and mapped to E-retaining coordinates; they are **not** independently decoded complete candidate trajectories. Every real state update does rerun the actual full decoder trajectory.','', '## Locked protocol','', 'Same exposed128 HC parents/queries and8 observations, E+finalMBR time/Source/decoder cache as the conditional-reference probe. Teacher target ONLY native ReferDINO selected8 trajectory, unchanged across all methods, rounds and seeds. Previous conditional T(S0) Direct was not reused. Eight independent256D per-video content states, frozen pretrained weights, zero-state exact E;40 Adam steps,lr.01,32 antithetic candidates,sigma.025,tau.05. Geometry cost mean8[5L1+2(1-GIoU)] and original Gaussian likelihood analytic baseline/control variate. The soft weights are constructed geometric supervision, not ReferDINO native probabilities.','', 'Direct recomputed once per parent (deterministic). Fixed samples NEW candidates from initial mean every round; Live samples NEW candidates from current decoded mean. Noise paired for each seed/parent/round. Seeds41,42,43 explicitly requested before locking; all reported. No scan, teacher/Source calls, new experts, new network training or observation positions. NH16 and reserved32 not run. All896 fits/128×8 output trajectories sealed before new GT evaluation.','', '## Primary parent-level effects','', 'Average each stochastic method metric across3 seeds WITHIN each parent, then bootstrap128 parents (10000 resamples). This is an expectation over reported seeds, not a box-averaged ensemble and not384 independent videos. Intervals condition on these three seeds; they do not establish robustness to all RNG seeds. Units pp.','', '| Comparison | Full vIoU [95% CI] | Known actual sIoU outside8 [95% CI] |','|---|---:|---:|']
 for k,v in z['primary']['paired'].items():text.append(f"| {k} | {show(v['v'])} | {show(v['unobserved_actual_s'])} |")
 for seed,g in z['by_seed'].items():
  text+=['',f'## Seed {seed}','', '| Comparison | Full vIoU [95% CI] | Outside8 actual sIoU [95% CI] |','|---|---:|---:|']
  for k,v in g['paired'].items():text.append(f"| {k} | {show(v['v'])} | {show(v['unobserved_actual_s'])} |")
 text+=['', '## Tails and actual updates','', 'All parents and known/unknown semantics retained; GT is only postseal evaluation. No per-parent output gates or best-step selection.',''];tails={}
 for arm in ['Direct','Fixed_seedmean','Live_seedmean']+[f'{a}_{s}'for s in z['seeds']for a in ['Fixed','Live']]:
  dd=sorted((100*(r['values'][arm]['v']-r['values']['E_MBR']['v']),r['alias'])for r in rows);vv=[v for v,a in dd];tails[arm]=dict(positive=sum(v>1e-12 for v in vv),negative=sum(v< -1e-12 for v in vv),unchanged=sum(abs(v)<=1e-12 for v in vv),below_minus3pp=sum(v< -3 for v in vv),below_minus5pp=sum(v< -5 for v in vv),worst5=dd[:5],best5=dd[-5:]);t=tails[arm];text.append(f"- {arm}: positive{t['positive']}, negative{t['negative']}, unchanged{t['unchanged']}; worse than−3pp:{t['below_minus3pp']}; worse than−5pp:{t['below_minus5pp']}. All signed rows and best/worst5 preserved.")
 update_summary={a:dict(fits=sum(1 for r in rows for n in r['fit_diagnostics']if n==a or n.startswith(a+'_')),updates=sum(f['updates']for r in rows for n,f in r['fit_diagnostics'].items()if n==a or n.startswith(a+'_')),mean_initial_anchor_loss=float(np.mean([f['initial_anchor_loss']for r in rows for n,f in r['fit_diagnostics'].items()if n==a or n.startswith(a+'_')])),mean_final_anchor_loss=float(np.mean([f['final_anchor_loss']for r in rows for n,f in r['fit_diagnostics'].items()if n==a or n.startswith(a+'_')])))for a in ['Direct','Fixed','Live']}
 text+=['', f"Actual state updates:{cost['actual_state_updates']}; complete trajectory decoder calls:{cost['trajectory_decoder_calls']} (offset calls:{cost['offset_decoder_calls']}); candidate geometry feedback evaluations:{cost['sampled_candidate_feedback']}. Per-method fit counts/losses in DECISION_PUBLIC.json; lower anchor loss or likelihood loss is not sufficient task evidence.",'', '## Cost, audit and decision scope','',f"New GPU allocation{cost['total_GPU_seconds']:.3f}s, including model loading, guards, actual decode/backpropagation and artifact overhead. No new Source/ReferDINO/DINO forwards. Prior expert/image-encoding cost has already been paid and is separately identified; it is not free. Direct/Fixed/Live use equal optimizer-step budgets, while actual feedback/gradient compute can differ. Per-query and per-fit timing retained.", '', 'Independent saved-artifact audit reconstructs paired RNG/noises/actions, fresh Fixed batches, current Live centers, mapping, geometry costs/weights, likelihood gradients and all actual Adam updates; checks native target/zero state/time/physical support, independent full/outside8 metrics and all parent bootstrap intervals. This is not a second full GPU replication.', '', 'This is one fixed configuration on previously exposed development data. No seed/domain/parent winner selection. A negative setting is not a claim about all hyperparameters or all OPD; a positive development effect is not independent confirmation. Live must be judged against BOTH Direct and the strengthened fresh Fixed control, plus E and severe losses. No automatic parameter sweep, held32 evaluation, additional observations or production promotion.']
 P.joinpath('REPORT.md').write_text('\n'.join(text)+'\n');put(P/'DECISION_PUBLIC.json',dict(status='completed_single_locked_configuration',seeds=z['seeds'],primary=z['primary'],by_seed=z['by_seed'],tails=tails,update_summary=update_summary,resource_decision='no automatic followup; assess Live-E, Live-Direct, Live-Fixed and tails together',no_production_promotion=True))
 P.joinpath('ROUND_REVIEW.md').write_text('''# Scientific / engineering review\n\nNative ReferDINO labels are fixed and common. OPD requires current student proposal feedback here, not changed teacher weights or changed teacher boxes. Fixed is strengthened to40 NEW random batches from initial policy, paired with Live in every round. Direct is newly run against native labels. Output-box exploration and actual deterministic full decoder trajectories are distinguished.\n\nSeeds41/42/43 were explicitly selected by user before lock/GPU; all outcomes retained. Primary averages seed metrics per parent then bootstraps128 parents; no pseudoreplication as384 videos, no best seed. All predictions before new GT, unknowns and zero-time/no-original-reference cases retained, current original E/time exact. No source/teacher inference or learned new head. Old conditional supervision/crop teacher/held-first Fixed results remain historical, not substituted here.\n\nA fixed numerical configuration is a mechanism comparison, not an optimal tuning claim. Different objective gradient scales can affect optimization. More candidate diversity is controlled for by fresh Fixed. Direct40 vs OPD40 matches steps but not all feedback computation; actual timing and counts reported. No stronger outcome conclusion follows from smaller loss, larger motion or teacher weighting alone.\n''')
 files=['vg_tta/stvg_referdino_native_opd_hc128_v1.py']+[str(f.relative_to(ROOT))for f in ROOT.joinpath('scripts').glob('*stvg_referdino_native_opd_hc128_v1.py')if not f.name.startswith('publish_')]+['protocols/stvg_referdino_native_opd_hc128_v1.md']+[str(f.relative_to(ROOT))for f in sorted(P.iterdir())if f.is_file()and f.name!='ROUND_REVIEW.md'];assert len(files)==len(set(files));put(D/'PUBLIC_FILES_FINAL.json',dict(files=files));print('REPORT READY',flush=True)
if __name__=='__main__':main()
